var fileEl=document.getElementById('file'),q=document.getElementById('q'),qv=document.getElementById('qv'),
fmt=document.getElementById('fmt'),mw=document.getElementById('mw'),go=document.getElementById('go'),
dl=document.getElementById('dl'),note=document.getElementById('note'),stats=document.getElementById('stats'),
prev=document.getElementById('prev'),prevWrap=document.getElementById('prevWrap');
var img=new Image(),srcSize=0,srcName='image',outBlob=null,outUrl=null;
function kb(b){return b<1024?b+' B':b<1048576?(b/1024).toFixed(1)+' KB':(b/1048576).toFixed(2)+' MB';}
q.addEventListener('input',function(){qv.textContent=q.value;});
fileEl.addEventListener('change',function(){
  var f=fileEl.files&&fileEl.files[0];
  if(!f){return;}
  if(!/^image\//.test(f.type)){note.textContent='That file is not an image.';return;}
  srcSize=f.size;srcName=f.name.replace(/\.[^.]+$/,'');
  var r=new FileReader();
  r.onload=function(e){
    img=new Image();
    img.onload=function(){go.disabled=false;note.textContent='Loaded '+img.width+' x '+img.height+' pixels, '+kb(srcSize)+'. Choose your settings and press Compress.';WT.resize();};
    img.onerror=function(){note.textContent='That image could not be read.';};
    img.src=e.target.result;
  };
  r.readAsDataURL(f);
});
go.addEventListener('click',function(){
  if(!img.width){return;}
  var w=img.width,h=img.height,max=parseInt(mw.value,10)||0;
  if(max>0&&w>max){h=Math.round(h*(max/w));w=max;}
  var c=document.createElement('canvas');c.width=w;c.height=h;
  var ctx=c.getContext('2d');
  if(fmt.value==='image/jpeg'){ctx.fillStyle='#fff';ctx.fillRect(0,0,w,h);}
  ctx.drawImage(img,0,0,w,h);
  c.toBlob(function(b){
    if(!b){note.textContent='Your browser could not produce that format. Try JPG.';return;}
    outBlob=b;
    if(outUrl){URL.revokeObjectURL(outUrl);}
    outUrl=URL.createObjectURL(b);
    document.getElementById('s1').textContent=kb(srcSize);
    document.getElementById('s2').textContent=kb(b.size);
    var saved=srcSize?Math.max(0,Math.round((1-b.size/srcSize)*100)):0;
    document.getElementById('s3').textContent=saved+'%';
    stats.style.display='';
    prev.src=outUrl;prevWrap.style.display='';
    dl.disabled=false;
    note.textContent='Done. New size '+w+' x '+h+' pixels. Press Download to save it.';
    WT.resize();
  },fmt.value,parseInt(q.value,10)/100);
});
dl.addEventListener('click',function(){
  if(!outBlob){return;}
  var ext=fmt.value==='image/png'?'png':fmt.value==='image/webp'?'webp':'jpg';
  var name=srcName+'-compressed.'+ext;
  try{
    var a=document.createElement('a');a.href=outUrl;a.download=name;
    document.body.appendChild(a);a.click();document.body.removeChild(a);
    note.textContent='Saved as '+name+'. Check your downloads folder. You can also right click the preview below and choose Save image as.';
  }catch(e){
    var wnd=window.open(outUrl,'_blank');
    note.textContent=wnd?'Opened the image in a new tab. Right click it and choose Save image as.':'Right click the preview below and choose Save image as.';
  }
  WT.resize();
});
